// Author: MiYu. Cross-native research commands, custom upgrade inheritance and production reentry consumers.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=3)throw std::runtime_error("Usage: war3_research_tests <data-root> <generated-map>");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto check=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto forge=vm.global("probe_forge").bits,second=vm.global("probe_second").bits,footman=vm.global("probe_footman").bits,type=ObjectData::code("R0T1");auto& states=session.config().players[0].states;float baseHP=std::bit_cast<float>(session.units().at(footman)->maxLife.bits());
        auto idType=[&](const char* raw,unsigned category){return vm.invoke("IsUnitIdType",std::array{vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(raw))),vm.handle("unittype",category)}).bits!=0;};auto unitCount=session.units().size();for(unsigned category:{0u,2u,3u,4u,5u,6u,7u,8u,9u,14u,15u,16u,17u,18u,19u,20u})check(idType("hfoo",category)==bool(vm.invoke("IsUnitType",std::array{vm.handle("unit",footman),vm.handle("unittype",category)}).bits),"Unit ID and initial unit classification differ");check(idType("z0u1",3) && !idType("z0u1",4) && idType("z0u1",15) && idType("z0u1",16) && !idType("z0u1",0) && idType("z0u1",7),"Custom unit type overrides or inherited weapon not consumed");check(!idType("z999",2) && session.units().size()==unitCount,"Unknown type or query mutated map units");bool unsupported=false;try{idType("hfoo",23);}catch(const std::exception& error){unsupported=std::string(error.what()).find("unsupported runtime state")!=std::string::npos;}check(unsupported,"Runtime-only unit classification did not report its boundary");
        auto objectName=[&](const char* raw){return vm.invoke("GetObjectName",std::array{vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(raw)))});};auto profileName=objectName("Q0N1"),emptyName=objectName("Q0N2"),unknownName=objectName("z999");check(profileName.text && *profileName.text=="Profile only" && !emptyName.text && unknownName.text && *unknownName.text=="Default string","Object profile-only, empty or missing name differs");auto quotedName=objectName("Q0N3"),quotedSingle=objectName("Q0N4"),multiName=objectName("R0T1"),variantName=objectName("R0T2"),inheritedName=objectName("R0T3");check(quotedName.text && *quotedName.text=="Alpha, Beta" && quotedSingle.text && *quotedSingle.text=="Solo, Title" && multiName.text && *multiName.text=="First" && variantName.text && *variantName.text=="Variant, first" && inheritedName.text && *inheritedName.text=="Base, first","Object name first item, quoted comma or inherited override differs");
        auto baseBuff=ObjectData::code("Bblo"),customBuff=ObjectData::code("B0T1");check(session.buffProfile(baseBuff,"Bufftip")=="Base buff title" && session.buffProfile(baseBuff,"Buffart")=="BaseBuffIcon.blp" && session.buffProfile(baseBuff,"Buffubertip")=="Base buff description" && session.buffProfile(baseBuff,"Targetart")=="BaseBuffEffect.mdx","Original buff overrides not consumed");check(session.buffProfile(customBuff,"Bufftip")=="Custom buff title" && session.buffProfile(customBuff,"Buffart")=="CustomBuffIcon.blp" && session.buffProfile(customBuff,"Buffubertip")=="Base buff description" && session.buffProfile(customBuff,"Targetart")=="BaseBuffEffect.mdx","Custom buff overrides or inherited effects not consumed");
        auto buttons=session.commands(forge,0);check(std::any_of(buttons.begin(),buttons.end(),[&](auto& button){return button.type==type && button.action==CommandAction::Research && button.gold==10 && button.lumber==7 && button.enabled && button.name=="First";}),"Custom upgrade not consumed by command panel");check(session.research(forge,type) && !session.research(second,type),"Duplicate research reservation was accepted");check(states.at(1)==990 && states.at(2)==993 && vm.global("probe_started").bits==1,"Research payment/start consumer differs");check(session.cancelProduction(forge) && states.at(1)==1000 && states.at(2)==1000 && vm.global("probe_cancelled").bits==1,"Research cancellation/refund consumer differs");
        auto player=vm.handle("player",0x100000);check(vm.invoke("IssueImmediateOrder",std::array{vm.handle("unit",forge),vm.string("R0T1")}).bits!=0,"String research command not consumed");session.advance(2);auto unit=session.units().at(footman);check(vm.global("probe_finished").bits==1 && unit->technology.dice==1 && unit->technology.damage==4 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+20,"Completed upgrade did not reach live unit");auto created=vm.invoke("CreateUnit",std::array{player,vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("hfoo"))),vm.real(unit->x),vm.real(unit->y),vm.real(unit->facing)});check(session.units().at(created.bits)->technology.dice==1,"New unit did not inherit research");check(session.research(forge,type),"Second level prerequisite override not consumed");session.advance(2);check(vm.global("probe_finished").bits==2 && unit->technology.dice==2 && unit->technology.damage==8 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+40,"Second level or repeated effect differed");
        vm.invoke("SetPlayerTechResearched",std::array{player,vm.integer(std::bit_cast<std::int32_t>(type)),vm.integer(0)});check(unit->technology.dice==2 && std::bit_cast<float>(unit->maxLife.bits())==baseHP+40,"SetPlayerTechResearched lowered existing research");vm.invoke("ProbeCancelOnStart");check(session.research(forge,type) && session.units().at(forge)->production.empty(),"Start callback cancellation corrupted queue");check(states.at(1)==975 && states.at(2)==983,"Reentrant cancellation lost refund");auto other=vm.invoke("Player",std::array{vm.integer(1)});for(auto [unitName,upgrade]:std::initializer_list<std::pair<const char*,const char*>>{{"hfoo","Rhpm"},{"ogru","Ropm"},{"ugho","Rupm"},{"earc","Repm"}}){auto raw=[&](const char* name){return vm.integer(std::bit_cast<std::int32_t>(ObjectData::code(name)));};auto soldier=vm.invoke("CreateUnit",std::array{player,raw(unitName),vm.real(unit->x),vm.real(unit->y),vm.real(unit->facing)});auto item=vm.invoke("CreateItem",std::array{raw("phea"),vm.real(unit->x),vm.real(unit->y)});check(vm.invoke("UnitInventorySize",std::array{soldier}).bits==0 && !vm.invoke("UnitAddItem",std::array{soldier,item}).bits,"Backpack was available before its upgrade");vm.invoke("SetPlayerTechResearched",std::array{player,raw(upgrade),vm.integer(1)});check(vm.invoke("UnitInventorySize",std::array{soldier}).bits==2 && vm.invoke("UnitAddItem",std::array{soldier,item}).bits,"Backpack upgrade did not enable pickup");vm.invoke("SetUnitOwner",std::array{soldier,other,vm.boolean(false)});check(vm.invoke("UnitInventorySize",std::array{soldier}).bits==0 && vm.invoke("UnitItemInSlot",std::array{soldier,vm.integer(0)}).bits==item.bits,"Owner change lost a held item or ignored requirements");vm.invoke("KillUnit",std::array{soldier});check(session.items().contains(item.bits) && !session.items().at(item.bits)->holder,"Owner change suppressed inventory death drop");vm.invoke("RemoveItem",std::array{item});vm.invoke("RemoveUnit",std::array{soldier});}auto heroInventory=vm.handle("unit",footman);check(vm.invoke("UnitAddAbility",std::array{heroInventory,vm.integer(std::bit_cast<std::int32_t>(ObjectData::code("AInv")))}).bits && vm.invoke("UnitInventorySize",std::array{heroInventory}).bits==6,"Unrestricted six-slot inventory was blocked");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS research consumers: custom levels, commands, payment/refund, duplicate lock, events, current/new units and callback cancellation\n";return 0;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
}
